273	class CodeActionOnSaveParticipant extends Disposable implements ITextFileSaveParticipant {
274	
275		constructor(
276			@IConfigurationService private readonly configurationService: IConfigurationService,
277			@IInstantiationService private readonly instantiationService: IInstantiationService,
278			@ILanguageFeaturesService private readonly languageFeaturesService: ILanguageFeaturesService,
279			@IHostService private readonly hostService: IHostService,
280			@IEditorService private readonly editorService: IEditorService,
281			@ICodeEditorService private readonly codeEditorService: ICodeEditorService,
282		) {
283			super();
284	
285			this._register(this.hostService.onDidChangeFocus(() => { this.triggerCodeActionsCommand(); }));
286			this._register(this.editorService.onDidActiveEditorChange(() => { this.triggerCodeActionsCommand(); }));
287		}
288	
289		private async triggerCodeActionsCommand() {
290			if (this.configurationService.getValue<boolean>('editor.codeActions.triggerOnFocusChange') && this.configurationService.getValue<string>('files.autoSave') === 'afterDelay') {
291				const model = this.codeEditorService.getActiveCodeEditor()?.getModel();
292				if (!model) {
293					return undefined;
294				}
295	
296				const settingsOverrides = { overrideIdentifier: model.getLanguageId(), resource: model.uri };
297				const setting = this.configurationService.getValue<{ [kind: string]: string | boolean } | string[]>('editor.codeActionsOnSave', settingsOverrides);
298	
299				if (!setting) {
300					return undefined;
301				}
302	
303				if (Array.isArray(setting)) {
304					return undefined;
305				}
306	
307				const settingItems: string[] = Object.keys(setting).filter(x => setting[x] && setting[x] === 'always' && CodeActionKind.Source.contains(new HierarchicalKind(x)));
308	
309				const cancellationTokenSource = new CancellationTokenSource();
310	
311				const codeActionKindList = [];
312				for (const item of settingItems) {
313					codeActionKindList.push(new HierarchicalKind(item));
314				}
315	
316				// run code actions based on what is found from setting === 'always', no exclusions.
317				await this.applyOnSaveActions(model, codeActionKindList, [], Progress.None, cancellationTokenSource.token);
318			}
319		}
320	
321		async participate(model: ITextFileEditorModel, context: ITextFileSaveParticipantContext, progress: IProgress<IProgressStep>, token: CancellationToken): Promise<void> {
322			if (!model.textEditorModel) {
323				return;
324			}
325	
326			const textEditorModel = model.textEditorModel;
327			const settingsOverrides = { overrideIdentifier: textEditorModel.getLanguageId(), resource: textEditorModel.uri };
328	
329			// Convert boolean values to strings
330			const setting = this.configurationService.getValue<{ [kind: string]: string | boolean } | string[]>('editor.codeActionsOnSave', settingsOverrides);
331			if (!setting) {
332				return undefined;
333			}
334	
335			if (context.reason === SaveReason.AUTO) {
336				return undefined;
337			}
338	
339			if (context.reason !== SaveReason.EXPLICIT && Array.isArray(setting)) {
340				return undefined;
341			}
342	
343			const settingItems: string[] = Array.isArray(setting)
344				? setting
345				: Object.keys(setting).filter(x => setting[x] && setting[x] !== 'never');
346	
347			const codeActionsOnSave = this.createCodeActionsOnSave(settingItems);
348	
349			if (!Array.isArray(setting)) {
350				codeActionsOnSave.sort((a, b) => {
351					if (CodeActionKind.SourceFixAll.contains(a)) {
352						if (CodeActionKind.SourceFixAll.contains(b)) {
353							return 0;
354						}
355						return -1;
356					}
357					if (CodeActionKind.SourceFixAll.contains(b)) {
358						return 1;
359					}
360					return 0;
361				});
362			}
363	
364			if (!codeActionsOnSave.length) {
365				return undefined;
366			}
367			const excludedActions = Array.isArray(setting)
368				? []
369				: Object.keys(setting)
370					.filter(x => setting[x] === 'never' || false)
371					.map(x => new HierarchicalKind(x));
372	
373			progress.report({ message: localize('codeaction', "Quick Fixes") });
374	
375			const filteredSaveList = Array.isArray(setting) ? codeActionsOnSave : codeActionsOnSave.filter(x => setting[x.value] === 'always' || ((setting[x.value] === 'explicit' || setting[x.value] === true) && context.reason === SaveReason.EXPLICIT));
376	
377			await this.applyOnSaveActions(textEditorModel, filteredSaveList, excludedActions, progress, token);
378		}
379	
380		private createCodeActionsOnSave(settingItems: readonly string[]): HierarchicalKind[] {
381			const kinds = settingItems.map(x => new HierarchicalKind(x));
382	
383			// Remove subsets
384			return kinds.filter(kind => {
385				return kinds.every(otherKind => otherKind.equals(kind) || !otherKind.contains(kind));
386			});
387		}
388	
389		private async applyOnSaveActions(model: ITextModel, codeActionsOnSave: readonly HierarchicalKind[], excludes: readonly HierarchicalKind[], progress: IProgress<IProgressStep>, token: CancellationToken): Promise<void> {
390	
391			const getActionProgress = new class implements IProgress<CodeActionProvider> {
392				private _names = new Set<string>();
393				private _report(): void {
394					progress.report({
395						message: localize(
396							{ key: 'codeaction.get2', comment: ['[configure]({1}) is a link. Only translate `configure`. Do not change brackets and parentheses or {1}'] },
397							"Getting code actions from {0} ([configure]({1})).",
398							[...this._names].map(name => `'${name}'`).join(', '),
399							createCommandUri('workbench.action.openSettings', 'editor.codeActionsOnSave').toString()
400						)
401					});
402				}
403				report(provider: CodeActionProvider) {
404					if (provider.displayName && !this._names.has(provider.displayName)) {
405						this._names.add(provider.displayName);
406						this._report();
407					}
408				}
409			};
410	
411			for (const codeActionKind of codeActionsOnSave) {
412				const actionsToRun = await this.getActionsToRun(model, codeActionKind, excludes, getActionProgress, token);
413	
414				if (token.isCancellationRequested) {
415					actionsToRun.dispose();
416					return;
417				}
418	
419				try {
420					for (const action of actionsToRun.validActions) {
421						progress.report({ message: localize('codeAction.apply', "Applying code action '{0}'.", action.action.title) });
422						await this.instantiationService.invokeFunction(applyCodeAction, action, ApplyCodeActionReason.OnSave, {}, token);
423						if (token.isCancellationRequested) {
424							return;
425						}
426					}
427				} catch {
428					// Failure to apply a code action should not block other on save actions
429				} finally {
430					actionsToRun.dispose();
431				}
432			}
433		}
434	
435		private getActionsToRun(model: ITextModel, codeActionKind: HierarchicalKind, excludes: readonly HierarchicalKind[], progress: IProgress<CodeActionProvider>, token: CancellationToken) {
436			return getCodeActions(this.languageFeaturesService.codeActionProvider, model, model.getFullModelRange(), {
437				type: CodeActionTriggerType.Auto,
438				triggerAction: CodeActionTriggerSource.OnSave,
439				filter: { include: codeActionKind, excludes: excludes, includeSourceActions: true },
440			}, progress, token);
441		}
442	}
443	
444	export class SaveParticipantsContribution extends Disposable implements IWorkbenchContribution {
445	
446		constructor(
447			@IInstantiationService private readonly instantiationService: IInstantiationService,
448			@ITextFileService private readonly textFileService: ITextFileService
449		) {
450			super();
451	
452			this.registerSaveParticipants();
453		}
454	
455		private registerSaveParticipants(): void {
456			this._register(this.textFileService.files.addSaveParticipant(this.instantiationService.createInstance(TrimWhitespaceParticipant)));
457			this._register(this.textFileService.files.addSaveParticipant(this.instantiationService.createInstance(CodeActionOnSaveParticipant)));
458			this._register(this.textFileService.files.addSaveParticipant(this.instantiationService.createInstance(FormatOnSaveParticipant)));
459			this._register(this.textFileService.files.addSaveParticipant(this.instantiationService.createInstance(FinalNewLineParticipant)));
460			this._register(this.textFileService.files.addSaveParticipant(this.instantiationService.createInstance(TrimFinalNewLinesParticipant)));
461		}
462	}
463	
464	const workbenchContributionsRegistry = Registry.as<IWorkbenchContributionsRegistry>(WorkbenchContributionsExtensions.Workbench);
465	workbenchContributionsRegistry.registerWorkbenchContribution(SaveParticipantsContribution, LifecyclePhase.Restored);
